-- Floor overlays: an upper floorplan aligned onto the floor below (by the
-- stairs), its wet areas, and moisture readings taken on the ceilings below.
-- One overlay per floorplan. Written by the inspector app (newest edit wins).
-- Safe to run more than once.

create table if not exists public.plan_overlays (
  -- Generated by the phone so offline edits keep their identity.
  id uuid primary key,
  job_id uuid not null references public.jobs(id) on delete cascade,
  floorplan_id uuid references public.job_floorplans(id) on delete set null,
  -- The floorplan this one is aligned onto (the floor below) and how:
  -- {"a","b","tx","ty","wu","hu","wl","hl"} – similarity transform in pixels.
  base_floorplan_id uuid references public.job_floorplans(id) on delete set null,
  align jsonb,
  -- [{"x1","y1","x2","y2" (0..1), "kind"}] on this floorplan.
  wet_areas jsonb not null default '[]'::jsonb,
  -- [{"x","y" (0..1), "value" (%), "note"}] taken on this floor's ceilings.
  moisture jsonb not null default '[]'::jsonb,
  deleted_at timestamptz,
  client_updated_at timestamptz not null,
  updated_by_staff_id uuid references public.staff(id) on delete set null,
  created_at timestamptz not null default now(),
  sync_rev bigint not null default nextval('public.inspection_sync_rev_seq'),
  updated_at timestamptz not null default now(),
  constraint plan_overlays_shape_check check (
    jsonb_typeof(wet_areas) = 'array' and jsonb_array_length(wet_areas) <= 100
    and jsonb_typeof(moisture) = 'array' and jsonb_array_length(moisture) <= 300
    and (align is null or jsonb_typeof(align) = 'object')
  )
);

create index if not exists plan_overlays_job_idx on public.plan_overlays (job_id, sync_rev);

drop trigger if exists plan_overlays_bump_rev on public.plan_overlays;
create trigger plan_overlays_bump_rev
before update on public.plan_overlays
for each row execute function private.bump_sync_rev();

alter table public.plan_overlays enable row level security;
revoke all on table public.plan_overlays from anon, authenticated;
drop policy if exists plan_overlays_select_assigned on public.plan_overlays;
create policy plan_overlays_select_assigned on public.plan_overlays
for select to authenticated using (private.can_view_job(job_id));
grant select on public.plan_overlays to authenticated;

create or replace function public.app_sync_plan_overlays(
  p_actor_user_id uuid,
  p_job_id uuid,
  p_overlays jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_staff public.staff%rowtype;
  v_item jsonb;
  v_existing public.plan_overlays%rowtype;
  v_applied uuid[] := '{}';
  v_stale uuid[] := '{}';
  v_id uuid;
  v_plan uuid;
  v_base uuid;
  v_client_at timestamptz;
begin
  v_staff := private.app_actor_for_job(p_actor_user_id, p_job_id);
  if jsonb_typeof(p_overlays) <> 'array' or jsonb_array_length(p_overlays) > 50 then
    raise exception 'Send between 0 and 50 floor overlays at a time.';
  end if;

  for v_item in select * from jsonb_array_elements(p_overlays) loop
    v_id := (v_item->>'id')::uuid;
    v_client_at := (v_item->>'clientUpdatedAt')::timestamptz;
    v_plan := nullif(v_item->>'floorplanId', '')::uuid;
    select * into v_existing from public.plan_overlays where id = v_id for update;
    if found then
      if v_existing.job_id <> p_job_id then raise exception 'Floor overlay belongs to another job.'; end if;
      if v_existing.client_updated_at > v_client_at then
        v_stale := v_stale || v_id;
        v_existing := null;
        continue;
      end if;
    end if;
    if v_plan is not null and not exists (
      select 1 from public.job_floorplans where id = v_plan and job_id = p_job_id
    ) then
      raise exception 'Floorplan does not belong to this job.';
    end if;
    v_base := nullif(v_item->>'baseFloorplanId', '')::uuid;
    if v_base is not null and (v_base = v_plan or not exists (
      select 1 from public.job_floorplans where id = v_base and job_id = p_job_id
    )) then
      raise exception 'The floor below does not belong to this job.';
    end if;

    insert into public.plan_overlays (
      id, job_id, floorplan_id, base_floorplan_id, align, wet_areas, moisture,
      deleted_at, client_updated_at, updated_by_staff_id
    ) values (
      v_id, p_job_id, v_plan, v_base,
      case when jsonb_typeof(v_item->'align') = 'object' then v_item->'align' else null end,
      coalesce(v_item->'wetAreas', '[]'::jsonb),
      coalesce(v_item->'moisture', '[]'::jsonb),
      case when (v_item->>'deleted')::boolean then coalesce(v_existing.deleted_at, now()) else null end,
      v_client_at, v_staff.id
    )
    on conflict (id) do update set
      floorplan_id = excluded.floorplan_id,
      base_floorplan_id = excluded.base_floorplan_id,
      align = excluded.align,
      wet_areas = excluded.wet_areas,
      moisture = excluded.moisture,
      deleted_at = excluded.deleted_at,
      client_updated_at = excluded.client_updated_at,
      updated_by_staff_id = excluded.updated_by_staff_id;

    v_applied := v_applied || v_id;
    v_existing := null;
  end loop;

  if cardinality(v_applied) > 0 then
    insert into public.audit_events (job_id, event_type, actor_type, actor_id, event_data)
    values (p_job_id, 'app_plan_overlays_synced', 'staff', v_staff.id::text,
      jsonb_build_object('applied', cardinality(v_applied), 'stale', cardinality(v_stale)));
  end if;
  return jsonb_build_object('applied', to_jsonb(v_applied), 'stale', to_jsonb(v_stale));
end;
$$;

revoke all on function public.app_sync_plan_overlays(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.app_sync_plan_overlays(uuid, uuid, jsonb) to service_role;
